previewCss:
.darma-loader-darma-b13-rubik-twist { --accent: var(--loader-color, #ef4444); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 100px); height: var(--loader-size, 100px); display: grid; grid-template-columns: repeat(3, 1fr); gap: 5%; padding: 5%; border-radius: 12%; background: #0b1220; animation: darma-loader-darma-b13-rubik-twist-quarter-turn calc(var(--loader-speed, 1s) * 3.6) cubic-bezier(.6, 0, .2, 1) infinite; }
.darma-loader-darma-b13-rubik-twist span { border-radius: 16%; background: var(--accent); animation: darma-loader-darma-b13-rubik-twist-recolor calc(var(--loader-speed, 1s) * 1.8) steps(2, end) infinite; }
.darma-loader-darma-b13-rubik-twist span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b13-rubik-twist span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b13-rubik-twist span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b13-rubik-twist span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b13-rubik-twist span:nth-child(6) { animation-delay: calc(var(--loader-speed, 1s) * 1); }
.darma-loader-darma-b13-rubik-twist span:nth-child(7) { animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b13-rubik-twist span:nth-child(8) { animation-delay: calc(var(--loader-speed, 1s) * 1.4); }
.darma-loader-darma-b13-rubik-twist span:nth-child(9) { animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
@keyframes darma-loader-darma-b13-rubik-twist-quarter-turn { 0%, 14% { transform: rotate(0deg); } 25%, 39% { transform: rotate(90deg); } 50%, 64% { transform: rotate(180deg); } 75%, 89% { transform: rotate(270deg); } 100% { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b13-rubik-twist-recolor { 0%, 100% { background: var(--accent); } 50% { background: var(--accent-2); } }

